import pandas as pd

def validate_row_count(src_count, tgt_count):
    assert src_count == tgt_count, f"Row count mismatch! SRC={src_count}, TGT={tgt_count}"

def validate_schema(src_df, tgt_df):
    assert list(src_df.columns) == list(tgt_df.columns), "Schema mismatch!"

def validate_data(src_df, tgt_df, key_cols):
    merged = pd.merge(src_df, tgt_df, on=key_cols, how="outer", indicator=True)
    mismatches = merged[merged["_merge"] != "both"]
    assert mismatches.empty, f"Data mismatch found:\n{mismatches}"

def validate_transformation(src_df, tgt_df, transform_fn):
    transformed = transform_fn(src_df.copy())
    pd.testing.assert_frame_equal(transformed, tgt_df, check_like=True)
